using System;using System.Collections.Generic;using System.Globalization;using System.IO;using System.Linq;using System.Text;using System.Text.RegularExpressions;using System.Threading;using System.Windows.Media;using System.Windows.Media.Imaging;using Microsoft.Win32;
namespace Iris {
    public sealed class SteamGame {public string Id,Name,Directory,Library;public ImageSource Icon;}
    public sealed class SteamLibraryResult {public SteamGame[] Games=new SteamGame[0];public string Message="";}
    public sealed class SteamValues {
        public string Key;public readonly Dictionary<string,string> Values=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);public readonly List<SteamValues> Children=new List<SteamValues>();
        public string Get(string name){string value;return Values.TryGetValue(name,out value)?value:"";}
        sealed class Reader {
            readonly string text;int position,entries;public Reader(string text){if(text.Length>2*1024*1024)throw new InvalidDataException(L.T("Steam-Datei zu groß."));this.text=text;}
            string Token(){while(position<text.Length){if(char.IsWhiteSpace(text[position])||text[position]=='\uFEFF'){position++;continue;}if(text[position]=='/'&&position+1<text.Length&&text[position+1]=='/'){while(position<text.Length&&text[position]!='\n')position++;continue;}break;}if(position==text.Length)return null;char c=text[position++];if(c=='{'||c=='}')return c.ToString();if(c=='"'){var value=new StringBuilder();bool closed=false;while(position<text.Length){c=text[position++];if(c=='"'){closed=true;break;}if(c=='\\'&&position<text.Length){c=text[position++];if(c=='n')c='\n';else if(c=='r')c='\r';else if(c=='t')c='\t';}value.Append(c);if(value.Length>32768)throw new InvalidDataException(L.T("Ungültiger Steam-Wert."));}if(!closed)throw new InvalidDataException(L.T("Unvollständige Steam-Datei."));return value.ToString();}int start=position-1;while(position<text.Length&&!char.IsWhiteSpace(text[position])&&text[position]!='{'&&text[position]!='}')position++;return text.Substring(start,position-start);}
            SteamValues Body(string key,int depth,bool closing){if(depth>16)throw new InvalidDataException(L.T("Steam-Datei zu tief verschachtelt."));var node=new SteamValues{Key=key};string name;while((name=Token())!=null){if(name=="}"){if(!closing)throw new InvalidDataException(L.T("Unerwartete Steam-Klammer."));return node;}if(name=="{"||++entries>50000)throw new InvalidDataException(L.T("Ungültige Steam-Struktur."));string value=Token();if(value==null||value=="}")throw new InvalidDataException(L.T("Unvollständiger Steam-Eintrag."));if(value=="{")node.Children.Add(Body(name,depth+1,true));else node.Values[name]=value;}if(closing)throw new InvalidDataException(L.T("Unvollständiger Steam-Block."));return node;}
            public SteamValues Parse(){return Body("",0,false);}
        }
        public static SteamValues Parse(string text){return new Reader(text).Parse();}
    }
    public static class SteamLibrary {
        public static string[] Roots(){var roots=new List<string>();try{using(var key=Registry.CurrentUser.OpenSubKey(@"Software\Valve\Steam")){string path=key==null?"":Convert.ToString(key.GetValue("SteamPath"));if(Path.IsPathRooted(path))roots.Add(path);}}catch{}foreach(string folder in new[]{Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles)})if(folder.Length>0)roots.Add(Path.Combine(folder,"Steam"));return roots.Where(Directory.Exists).Select(Path.GetFullPath).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();}
        static string ReadSmall(string path,int limit){using(var stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){if(stream.Length>limit)throw new InvalidDataException(L.T("Steam-Datei zu groß."));using(var reader=new StreamReader(stream,Encoding.UTF8,true))return reader.ReadToEnd();}}
        static string Under(string root,string relative){if(string.IsNullOrWhiteSpace(relative)||Path.IsPathRooted(relative)||relative.IndexOfAny(new[]{'\0','\r','\n'})>=0)return null;string parent=Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;string path=Path.GetFullPath(Path.Combine(parent,relative));return path.StartsWith(parent,StringComparison.OrdinalIgnoreCase)?path:null;}
        public static SteamGame Manifest(string text,string path){var tree=SteamValues.Parse(text);var state=tree.Children.FirstOrDefault(n=>string.Equals(n.Key,"AppState",StringComparison.OrdinalIgnoreCase));if(state==null)return null;string id=state.Get("appid"),name=state.Get("name");long flags;if(!Regex.IsMatch(id,@"^[1-9][0-9]{0,9}$")||!string.Equals(Path.GetFileName(path),"appmanifest_"+id+".acf",StringComparison.OrdinalIgnoreCase)||name.Length==0||name.Length>256||name.Any(char.IsControl)||!long.TryParse(state.Get("StateFlags"),NumberStyles.None,CultureInfo.InvariantCulture,out flags)||(flags&4)==0)return null;if(id=="228980"||id=="1007")return null;string apps=Path.GetDirectoryName(path),directory=Under(Path.Combine(apps,"common"),state.Get("installdir"));if(directory==null)return null;return new SteamGame{Id=id,Name=name,Directory=directory,Library=Path.GetDirectoryName(apps)};}
        public static SteamLibraryResult Read(CancellationToken token){return Read(Roots(),token,true);}
        public static SteamLibraryResult Read(IEnumerable<string> steamRoots,CancellationToken token,bool icons){var roots=steamRoots.Where(p=>!string.IsNullOrWhiteSpace(p)&&Path.IsPathRooted(p)).Select(Path.GetFullPath).Distinct(StringComparer.OrdinalIgnoreCase).Take(16).ToArray();var libraries=new HashSet<string>(roots,StringComparer.OrdinalIgnoreCase);int unreadable=0;
            foreach(string root in roots){token.ThrowIfCancellationRequested();try{string file=Path.Combine(root,"steamapps","libraryfolders.vdf");if(!File.Exists(file))continue;var tree=SteamValues.Parse(ReadSmall(file,2*1024*1024));var folders=tree.Children.FirstOrDefault(n=>string.Equals(n.Key,"libraryfolders",StringComparison.OrdinalIgnoreCase));if(folders==null)continue;foreach(string path in folders.Children.Select(n=>n.Get("path")).Concat(folders.Values.Where(kv=>Regex.IsMatch(kv.Key,@"^\d+$")).Select(kv=>kv.Value))){if(libraries.Count>=64)break;if(!string.IsNullOrWhiteSpace(path)&&Path.IsPathRooted(path))libraries.Add(Path.GetFullPath(path));}}catch(OperationCanceledException){throw;}catch{unreadable++;}}
            var games=new Dictionary<string,SteamGame>(StringComparer.Ordinal);foreach(string library in libraries){token.ThrowIfCancellationRequested();string apps=Path.Combine(library,"steamapps");if(!System.IO.Directory.Exists(apps))continue;try{foreach(string file in System.IO.Directory.EnumerateFiles(apps,"appmanifest_*.acf").Take(4096)){token.ThrowIfCancellationRequested();try{var game=Manifest(ReadSmall(file,256*1024),file);if(game!=null&&System.IO.Directory.Exists(game.Directory)&&!games.ContainsKey(game.Id)){if(icons)game.Icon=ReadIcon(roots,game.Id,token);games.Add(game.Id,game);if(games.Count>=4096)break;}}catch(OperationCanceledException){throw;}catch{unreadable++;}}}catch(OperationCanceledException){throw;}catch{unreadable++;}}
            token.ThrowIfCancellationRequested();return new SteamLibraryResult{Games=games.Values.OrderBy(g=>g.Name,StringComparer.CurrentCultureIgnoreCase).ToArray(),Message=games.Count==0?L.T("Keine installierten Steam-Spiele gefunden. Starte Steam einmal und klicke anschließend auf „Aktualisieren“."):unreadable>0?L.T("Einige Steam-Dateien konnten nicht gelesen werden. Du kannst die Liste aktualisieren."):""};
        }
        static ImageSource ReadIcon(string[] roots,string id,CancellationToken token){foreach(string root in roots){token.ThrowIfCancellationRequested();string cache=Path.Combine(root,"appcache","librarycache");var candidates=new List<string>{Path.Combine(cache,id+"_icon.jpg"),Path.Combine(cache,id+"_icon.png")};string folder=Path.Combine(cache,id);try{if(System.IO.Directory.Exists(folder))candidates.AddRange(System.IO.Directory.EnumerateFiles(folder).Where(p=>new[]{".jpg",".jpeg",".png"}.Contains(Path.GetExtension(p).ToLowerInvariant())).Take(16));}catch{}foreach(string path in candidates){token.ThrowIfCancellationRequested();try{if(!File.Exists(path))continue;using(var stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){if(stream.Length<16||stream.Length>1024*1024)continue;var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.DecodePixelWidth=40;image.StreamSource=stream;image.EndInit();if(image.PixelHeight<30||image.PixelHeight>52)continue;image.Freeze();return image;}}catch{}}}return null;}
    }
}
